@font-face { font-family: "Space Grotesk"; font-style: normal; font-weight: 300 700; font-display: swap; src: url("assets/fonts/spacegrotesk/spacegrotesk-300-700.woff2") format("woff2"); }
@font-face { font-family: Tomorrow; font-style: normal; font-weight: 400; font-display: swap; src: url("assets/fonts/tomorrow/tomorrow-400.woff2") format("woff2"); }
@font-face { font-family: "Sofia Sans"; font-style: normal; font-weight: 1 1000; font-display: swap; src: url("assets/fonts/sofiasans/sofiasans-1-1000.woff2") format("woff2"); }
@font-face { font-family: Sora; font-style: normal; font-weight: 100 800; font-display: swap; src: url("assets/fonts/sora/sora-100-800.woff2") format("woff2"); }
@font-face { font-family: Recursive; font-style: normal; font-weight: 300 1000; font-display: swap; src: url("assets/fonts/recursive/recursive-300-1000.woff2") format("woff2"); }
@font-face { font-family: "Major Mono Display"; font-style: normal; font-weight: 400; font-display: swap; src: url("assets/fonts/majormonodisplay/majormonodisplay-400.woff2") format("woff2"); }
:root { --ground: #fafafa; --panel: #ffffff; --ink: #0f0f0f; --dim: #4f4a40; --line: #b9b2a2; --line-soft: #e2ddd1; --live: #0E7490; --live-bg: #EDF6F8; --hard: #d32f2f; --hard-bg: #fbeeee; --soft: #f57c00; --soft-bg: #fef3e6; --clean: #388e3c; --clean-bg: #edf5ed; --shadow: 0 1px 2px rgba(0,0,0,.06),0 2px 8px rgba(0,0,0,.05); --mono: ui-monospace,'SF Mono',Menlo,Consolas,monospace; --ff-space: "Space Grotesk",system-ui,-apple-system,"Segoe UI",Roboto,sans-serif; --ff-tomorrow: "Tomorrow",system-ui,-apple-system,"Segoe UI",Roboto,sans-serif; --ff-sofia: "Sofia Sans",system-ui,-apple-system,"Segoe UI",Roboto,sans-serif; --ff-sora: "Sora",system-ui,-apple-system,"Segoe UI",Roboto,sans-serif; --ff-recursive: "Recursive",system-ui,-apple-system,"Segoe UI",Roboto,sans-serif; --code-bg: #171717; --code-ink: #dcd8cf; }
* { box-sizing: border-box; margin: 0px; }
body { background: var(--ground); color: var(--ink); font: 15px/1.62 var(--ff-recursive); }
code, pre { font-family: var(--mono); }
.topbar { display: flex; gap: 20px; align-items: baseline; flex-wrap: wrap; max-width: 1086px; width: calc(100% - 64px); margin: 0px auto; padding: 22px 0px 12px; font-size: 13px; border-bottom: 3px double var(--ink); }
.topbar .brand { font-family: var(--ff-space); font-weight: 550; letter-spacing: 0.01em; font-size: 17px; color: var(--ink); }
.cols { display: grid; grid-template-columns: minmax(0px, 1fr) 312px; gap: 32px; max-width: 1150px; margin: 0px auto; padding: 14px 32px 64px; align-items: start; }
@media (max-width: 820px) {
  .cols { grid-template-columns: 1fr; }
}
.cols.full { grid-template-columns: minmax(0px, 1fr); }
.cols.full .instrument { display: none; }
.main-col { min-width: 0px; }
.pane-slot { margin-top: 20px; }
.pane-slot:not([data-hover="true"]):not([data-focus="true"]):not([data-open="true"]) > [data-role="live-pane"] { visibility: hidden; height: 0px; overflow: hidden; padding: 0px; border-width: 0px; box-shadow: none; }
.lp-bar { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 4px 12px; width: 100%; padding: 12px 20px; background: var(--panel); border: 1px solid var(--line); border-radius: 0px; box-shadow: var(--shadow); cursor: pointer; text-align: left; font-family: var(--ff-sofia); font-size: 11.5px; font-weight: 600; letter-spacing: 0.12em; text-transform: uppercase; color: var(--dim); }
.lp-bar:hover { color: var(--ink); }
.lp-bar .hint { font-weight: 400; letter-spacing: normal; text-transform: none; }
.pane-slot > [data-role="live-pane"] { border-top-width: medium; border-top-style: none; border-top-color: currentcolor; }
.stepcard { background: var(--panel); border-radius: 0px; border: 1px solid var(--line); box-shadow: var(--shadow); padding: 32px 36px; }
.stepcard h1, .stepcard .title, main h2 { font-family: var(--ff-space); font-weight: 550; letter-spacing: 0.01em; font-size: 29px; line-height: 1.22; margin: 0px 0px 14px; text-wrap: balance; }
.eyebrow { font-family: var(--ff-sofia); font-size: 12px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dim); margin: 0px 0px 12px; }
.stepcopy { color: var(--ink); margin: 0px 0px 26px; }
.stepcopy em { color: var(--dim); font-style: normal; }
.stepcopy p { margin: 0px 0px 14px; }
.stepcopy p:last-child { margin-bottom: 0px; }
.stepcard p, .entrybox p, .task p { margin: 0px 0px 12px; }
.stepcard p:last-child, .entrybox p:last-child, .task p:last-child { margin-bottom: 0px; }
.stepcard ul, .stepcard ol, .entrybox ul, .entrybox ol { margin: 0px 0px 12px; padding-left: 20px; }
#card p, #card li { text-align: justify; hyphens: auto; hyphenate-limit-chars: 6 3 3; }
#card .question, #card .replicate h3, #card pre, #card code { text-align: left; hyphens: manual; }
.task { background: var(--ground); border-radius: 0px; padding: 22px 24px; margin: 0px 0px 18px; }
.question { font-size: 17px; font-weight: 600; margin: 0px 0px 16px; }
.answerchip { background: var(--panel); border-radius: 4px; box-shadow: inset 0 0 0 1px var(--line); padding: 12px 14px; margin: 0px 0px 18px; }
.answerchip code { font-family: var(--mono); font-size: 14px; line-height: 1.5; }
.answerchip .hint { display: block; margin-top: 8px; }
textarea, input[type="text"] { width: 100%; font: inherit; padding: 10px 12px; border: 1px solid var(--line); border-radius: 4px; background: var(--panel); color: var(--ink); resize: vertical; }
textarea { min-height: 74px; }
input[type="text"] { max-width: 440px; }
textarea:focus, input[type="text"]:focus { outline: 2px solid var(--ink); outline-offset: -1px; }
.autotype-field.busy { background: var(--panel); color: var(--dim); cursor: not-allowed; }
.hint { font-family: var(--ff-tomorrow); font-size: 12px; color: var(--dim); }
.rule { padding: 14px 16px; background: var(--panel); border-top-color: ; border-top-style: ; border-top-width: ; border-right-color: ; border-right-style: ; border-right-width: ; border-bottom-color: ; border-bottom-style: ; border-bottom-width: ; border-image-source: ; border-image-slice: ; border-image-width: ; border-image-outset: ; border-image-repeat: ; border-left: 3px solid var(--soft); border-radius: 4px; margin: 0px 0px 14px; font-family: var(--ff-tomorrow); font-size: 15px; }
.rule.fallback-note { border-left-color: var(--soft); }
.btnrow { display: flex; flex-direction: column; align-items: center; gap: 14px; margin-top: 28px; }
.btnrow .btn { font-size: 17px; padding: 14px 28px; }
.btnrow .btn-back { order: 1; }
.btn { font-style: inherit; font-variant: inherit; font-stretch: inherit; font-size: inherit; line-height: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-family: var(--ff-recursive); font-weight: 600; padding: 10px 22px; border-radius: 4px; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; background: var(--ink); color: rgb(255, 255, 255); cursor: pointer; }
.btn:hover { background: rgb(43, 43, 43); }
.btn:disabled { background: var(--line); color: var(--dim); cursor: not-allowed; }
.btn:focus-visible, button:focus-visible, a:focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; }
.btn.btn-back { font-size: 14px; padding: 8px 16px; background: rgb(238, 244, 251); color: var(--ink); border: 1px solid var(--ink); }
.btn.btn-back:hover { background: rgb(226, 235, 248); }
.secondary { margin-top: 14px; font-size: 13.5px; }
.secondary a { color: var(--dim); text-decoration: underline; text-underline-offset: 3px; }
.skip { color: var(--dim); text-decoration: underline; text-underline-offset: 3px; }
.skip:hover { color: var(--ink); }
.entrybox { background: var(--ground); border-radius: 0px; padding: 22px 24px; margin: 0px 0px 18px; }
.endguard-row { text-align: center; }
.endguard { display: inline-block; font-style: inherit; font-variant: inherit; font-stretch: inherit; font-size: inherit; line-height: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-family: var(--ff-recursive); font-weight: 600; padding: 10px 22px; border-radius: 4px; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; background: var(--ink); color: rgb(255, 255, 255); cursor: pointer; margin-top: 14px; }
.endguard:hover { background: rgb(43, 43, 43); }
.endguard:focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; }
.endguard.floating { position: fixed; right: 24px; bottom: 24px; z-index: 2147483647; margin: 0px; border: 1px solid rgba(255, 255, 255, 0.35); box-shadow: rgba(0, 0, 0, 0.45) 0px 6px 24px; }
pre { background: var(--code-bg); color: var(--code-ink); padding: 14px 16px; border-radius: 0px; overflow-x: auto; font: 12.5px/1.5 var(--mono); margin: 0px 0px 18px; }
pre code { background: none; padding: 0px; }
.violations { display: flex; gap: 8px; flex-wrap: wrap; margin: 0px 0px 14px; }
.violations:empty { display: none; }
.chip { font-family: var(--ff-sora); font-size: 12px; padding: 4px 10px; border-radius: 0px; box-shadow: inset 0 0 0 1px var(--line); color: var(--dim); }
.chip.hot { background: var(--hard-bg); color: var(--hard); box-shadow: none; }
.instrument { position: sticky; top: 22px; }
.card { background: var(--panel); border-radius: 0px; border: 1px solid var(--line); box-shadow: var(--shadow); padding: 18px 20px; }
.card h3, .lp-title { font-family: var(--ff-sofia); font-size: 11.5px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--dim); font-weight: 600; margin: 0px 0px 4px; }
.signal-box { border: 1px solid var(--line); padding: 8px 10px; min-height: calc(1lh + 18px); margin: 0px 0px 12px; font-size: 13px; }
.signal-box-empty { color: var(--dim); }
.detected-strip { color: var(--clean); }
.check { list-style: none; margin: 10px 0px 0px; padding: 0px; font-size: 12.5px; max-height: calc(-220px + 100vh); overflow-y: auto; }
.check li { display: flex; align-items: center; gap: 9px; padding: 3px 0px; color: var(--dim); }
.check li.lit { color: var(--ink); }
.check li.lit .lamp { background: var(--clean); border-color: var(--clean); }
.check li.lit.hardlit .lamp { background: var(--hard); border-color: var(--hard); }
.check li.always .lamp { background: var(--line-soft); border-color: var(--line-soft); }
@keyframes rec-pulse { 
  50% { opacity: 0.25; }
}
.check li.recording .lamp { animation: 1.2s ease-in-out 0s infinite normal none running rec-pulse; background: var(--hard); border-color: var(--hard); }
@media (prefers-reduced-motion: reduce) {
  .check li.recording .lamp { animation: auto ease 0s 1 normal none running none; }
}
.check li .n { margin-left: auto; font-family: var(--ff-sora); font-variant-numeric: tabular-nums; font-size: 11.5px; }
.check .hint { font-family: var(--ff-sofia); padding-top: 12px; font-size: 10.5px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--dim); }
.check.awaiting li:not(.hint) { opacity: 0.55; }
.check.awaiting li.recording { opacity: 1; }
.lamp { flex: 0 0 auto; width: 8px; height: 8px; border-radius: 50%; border: 1.5px solid var(--line-soft); background: transparent; }
body[data-view="act2"] .check li.guardrow { color: var(--hard); }
body[data-view="act2"] .check li.guardrow .lamp { background: var(--hard); border-color: var(--hard); }
@keyframes lamp-pulse { 
  0% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.8); opacity: 0.4; }
  100% { transform: scale(1); opacity: 1; }
}
.lamp.lamp-pulse { animation: 0.6s ease-out 0s 1 normal none running lamp-pulse; }
@media (prefers-reduced-motion: reduce) {
  .lamp.lamp-pulse { animation: auto ease 0s 1 normal none running none; }
}
.lp-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 0px 0px 10px; }
.lp-tabs { display: flex; gap: 0px; }
.lp-tab { font: 12px var(--ff-recursive); padding: 4px 8px; border: 1px solid var(--line); border-radius: 0px; margin-left: -1px; background: var(--panel); color: var(--ink); cursor: pointer; white-space: nowrap; }
.lp-tab:first-child { border-radius: 4px 0px 0px 4px; margin-left: 0px; }
.lp-tab:last-child { border-radius: 0px 4px 4px 0px; }
.lp-tab.active { background: var(--ink); color: var(--panel); border-color: var(--ink); position: relative; z-index: 1; }
.lp-body { display: grid; gap: 8px; }
[data-role="live-pane"] .lp-body { grid-template-columns: 156px minmax(0px, 1fr); }
.lp-trials { display: flex; flex-direction: column; gap: 4px; min-width: 0px; flex: 0 0 auto; border-right: 1px solid var(--line-soft); padding-right: 8px; max-height: 560px; overflow-y: auto; }
.lp-trial-tab { font-family: inherit; font-size: 12px; line-height: 1.35; text-align: left; padding: 4px 6px; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; border-radius: 4px; background: var(--ground); color: var(--dim); cursor: pointer; flex: 0 0 auto; }
.lp-trial-tab[aria-pressed="true"] { background: var(--panel); color: var(--ink); box-shadow: inset 0 0 0 2px var(--ink); }
.lp-views { min-width: 0px; }
.lp-stream { font-family: var(--mono); font-size: 11.8px; line-height: 1.5; max-height: 560px; overflow-y: auto; }
.lp-cols, .lp-row { display: grid; gap: 8px; grid-template-columns: 44px minmax(90px, 0.8fr) minmax(140px, 1.19fr) minmax(0px, 2fr); padding: 4px 0px; border-top: 1px solid var(--line-soft); }
.lp-trial, .lp-event { overflow-wrap: break-word; overflow: hidden; }
.lp-detail { overflow-wrap: anywhere; }
.lp-cols { font-family: var(--ff-sofia); color: var(--dim); font-size: 10px; text-transform: uppercase; letter-spacing: 0.06em; border-top-width: medium; border-top-style: none; border-top-color: currentcolor; }
.lp-t { font-family: var(--mono); color: var(--dim); font-variant-numeric: tabular-nums; white-space: nowrap; }
.lp-trial { color: var(--dim); }
.lp-event { font-weight: 600; }
.lp-detail { color: var(--dim); }
.lp-row.hard .lp-event { color: var(--hard); font-weight: 700; }
.lp-row.lp-off { display: none; }
[data-role="live-pane"] .lp-body[data-view="json"] { grid-template-columns: minmax(0px, 1fr); }
.lp-body[data-view="json"] .lp-trials { display: none; }
.lp-json { background: none; color: var(--ink); margin: 0px; padding: 0px; border-radius: 0px; max-height: 560px; overflow: auto; font: 11.8px/1.6 var(--mono); }
.handoff { display: flex; gap: 14px; align-items: center; flex-wrap: wrap; margin: 0px 0px 8px; }
.batch-head { display: flex; gap: 14px; align-items: center; flex-wrap: wrap; margin: 18px 0px 8px; }
.batch-heading { font-family: var(--ff-sofia); font-size: 15px; font-weight: 600; margin: 0px; }
.files { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 10px; margin: 0px 0px 14px; }
.file { display: flex; flex-direction: column; gap: 10px; min-width: 0px; background: var(--panel); box-shadow: var(--shadow); border: 1px solid var(--line); border-radius: 0px; padding: 10px 14px; font: 13px/1.4 var(--mono); }
.file-info { display: flex; flex-direction: column; gap: 2px; }
.file small { display: block; font-family: var(--ff-recursive); color: var(--dim); font-size: 11px; }
.file .file-desc { display: block; font-family: var(--ff-recursive); color: var(--dim); font-size: 11px; }
.file .file-actions { display: flex; gap: 12px; align-items: center; margin-top: auto; }
.file .file-actions a { color: var(--ink); font-size: 12px; text-decoration: underline; text-underline-offset: 3px; }
.file .file-actions a.btn { color: rgb(255, 255, 255); font-size: inherit; text-decoration: none; }
.file-caveat { font-family: var(--ff-recursive); color: var(--dim); font-size: 11px; font-style: italic; }
.filetext-dialog { max-width: 640px; width: 90vw; padding: 18px; border: 1px solid var(--line); border-radius: 0px; box-shadow: var(--shadow); background: var(--panel); color: var(--ink); }
.filetext-dialog::backdrop { background: rgba(0, 0, 0, 0.4); }
.filetext-dialog h3 { margin: 0px 0px 10px; font: 600 13px/1 var(--ff-sofia); }
.filetext-dialog pre { max-height: 60vh; overflow: auto; user-select: text; margin: 0px 0px 14px; }
.replicate-title { font-family: var(--ff-sofia); font-size: 17px; font-weight: 600; letter-spacing: normal; line-height: 1.3; margin: 32px 0px 10px; }
.replicate h3 { font-family: var(--ff-sofia); font-size: 15px; font-weight: 600; margin: 18px 0px 8px; }
.replicate-title + h3 { margin-top: 0px; }

